-- ============================================================
-- 0095_tochka_reconciliation — сверка 16 счетов Точки с банковской выпиской 1С
-- (01.12.2023–16.10.2026, 68 файлов, 11 856 операций), решение владельца 2026-10-17.
--
-- Источник истины — выписка банка. После миграции каждый из 16 счетов совпадает
-- с выпиской построчно, по дням и месяцам, а остаток на 16.10.2026 — до копейки;
-- opening_balance = 0 (по выписке все счета на 01.12.2023 имели остаток 0,00).
--
-- Что делается (284 существующих строк + 39 новых):
--   delete   50 — balance_correction 31.12.2025, ручные/CSV-дубли банковских
--                операций и «переводы», которых в банке не было
--   flip    101 — входящие переводы с архивного счёта …183872 были записаны
--                импортом как исходящие (источник/получатель поменяны местами)
--   reroute  15 — переводы со Счета Лицензии привязаны не к тому фонду
--                (в банке получатель — Счет Услуги / Прочие платежи)
--   setside  45 — переводы на …183872 без счёта-получателя
--   convert  73 — «Отчисление в фонд Резерв» на …183872 записано расходом → перевод
--   insert   39 — операции из выписки, которых не было в сервисе
--   license_payments 3b503aed: перевешен с удаляемого ручного дубля на банковскую строку
--   accounts: opening_balance = 0 у 16 счетов
--
-- Весь файл — одна транзакция (DO-блок). Любая проверка, которая не сошлась,
-- откатывает всё, включая архив. Репетиция без изменений:
--   select set_config('recon0095.rehearsal', 'on', false);
-- Откат после фиксации: rollback/0095_down.sql.
-- ============================================================

create table if not exists public.recon0095_transactions_before as
  select t.*, now() as archived_at, ''::text as action from public.transactions t where false;
create table if not exists public.recon0095_accounts_before (
  account_id uuid primary key, account_name text, opening_before bigint not null, archived_at timestamptz not null default now());
create table if not exists public.recon0095_license_payments_before as
  select lp.*, now() as archived_at from public.license_payments lp where false;
create table if not exists public.recon0095_inserted (
  transaction_id uuid primary key, import_batch_id uuid not null, created_at timestamptz not null default now());
alter table public.recon0095_transactions_before enable row level security;
alter table public.recon0095_accounts_before enable row level security;
alter table public.recon0095_license_payments_before enable row level security;
alter table public.recon0095_inserted enable row level security;
revoke all on public.recon0095_transactions_before from anon, authenticated, public;
revoke all on public.recon0095_accounts_before from anon, authenticated, public;
revoke all on public.recon0095_license_payments_before from anon, authenticated, public;
revoke all on public.recon0095_inserted from anon, authenticated, public;

do $$
declare
  team uuid := '468b62b2-227e-4021-9e56-379e4b9ca6de';
  n int; n_bad int; batch uuid; r record; other_before bigint; other_after bigint;
begin
  if exists (select 1 from public.recon0095_inserted) then
    raise exception '0095: уже применена (recon0095_inserted не пуст)';
  end if;

  create temporary table _acc (sfx text primary key, id uuid not null unique) on commit drop;

  create temporary table _plan (id uuid primary key, action text not null, exp_type text not null, exp_amount bigint not null,
    exp_a text not null, exp_t text not null, new_a text, new_t text) on commit drop;

  create temporary table _ins (kind text, amount bigint, frm text, too text, occurred_on date, note text, num text) on commit drop;

  create temporary table _bank_month (sfx text, mon text, net bigint, primary key (sfx, mon)) on commit drop;
  create temporary table _bank_end (sfx text primary key, bal bigint) on commit drop;

  -- 1. каждая строка плана существует и выглядит ровно так, как при сверке (иначе данные поехали)
  select count(*) into n from _plan p join transactions t on t.id = p.id
    left join _acc a1 on a1.id = t.account_id left join _acc a2 on a2.id = t.transfer_account_id
   where t.team_id = team and t.status = 'actual' and t.currency = 'RUB'
     and left(t.type::text, 1) = p.exp_type and t.amount = p.exp_amount
     and coalesce(a1.sfx, case when t.account_id is null then '' else 'X' end) = p.exp_a
     and coalesce(a2.sfx, case when t.transfer_account_id is null then '' else 'X' end) = p.exp_t
     and (p.action <> 'convert' or (t.obligation_id is null and t.category_id is null));
  if n <> 284 then raise exception '0095: план не совпал с данными (% из 284)', n; end if;
  if (select count(*) from _ins) <> 39 then raise exception '0095: вставок не 39'; end if;

  -- 2. у удаляемых строк нет зависимостей, кроме известного платежа по лицензии
  select count(*) into n_bad from _plan p
   where p.action = 'delete' and (
         exists (select 1 from obligation_payments x where x.transaction_id = p.id)
      or exists (select 1 from obligations x where x.source_transaction_id = p.id)
      or exists (select 1 from invoices x where x.paid_transaction_id = p.id)
      or exists (select 1 from attachments x where x.transaction_id = p.id)
      or exists (select 1 from transaction_splits x where x.transaction_id = p.id)
      or exists (select 1 from license_deals x where x.income_transaction_id = p.id)
      or exists (select 1 from license_purchases x where x.expense_transaction_id = p.id)
      or exists (select 1 from license_payments x where x.income_transaction_id = p.id
                  and x.id <> '3b503aed-e638-4ac5-9601-f916befcc0f5'));
  if n_bad > 0 then raise exception '0095: у % удаляемых строк есть зависимости', n_bad; end if;

  -- 3. снимок «до»: суммарный остаток всех остальных счетов не должен измениться
  select coalesce(sum(a.opening_balance), 0)
       + coalesce((select sum(case t.type when 'income' then t.amount else -t.amount end) from transactions t
                    where t.status = 'actual' and t.account_id not in (select id from _acc)), 0)
       + coalesce((select sum(coalesce(t.transfer_amount, t.amount)) from transactions t
                    where t.status = 'actual' and t.type = 'transfer' and t.transfer_account_id not in (select id from _acc)), 0)
    into other_before from accounts a where a.id not in (select id from _acc);

  -- 4. архив
    select a.id, a.name, a.opening_balance from accounts a join _acc using (id);
    select lp.*, now() from license_payments lp where lp.id = '3b503aed-e638-4ac5-9601-f916befcc0f5';

  -- 5. изменения
  update license_payments set income_transaction_id = 'b00e78bd-ce48-46fa-a1de-6064c574e07c'
   where id = '3b503aed-e638-4ac5-9601-f916befcc0f5' and income_transaction_id = '8a3497ce-cc11-4711-abd3-7423f27b00ca';
  get diagnostics n = row_count;
  if n <> 1 then raise exception '0095: платёж по лицензии не перевешен'; end if;

  delete from transactions where id in (select id from _plan where action = 'delete');
  get diagnostics n = row_count;
  if n <> 50 then raise exception '0095: удалено % строк вместо 50', n; end if;

  update transactions t
     set account_id = (select id from _acc where sfx = p.new_a),
         transfer_account_id = (select id from _acc where sfx = p.new_t)
    from _plan p where t.id = p.id and p.action in ('flip', 'reroute', 'setside');
  get diagnostics n = row_count;
  if n <> 161 then raise exception '0095: перепривязано % строк', n; end if;

  update transactions t
     set type = 'transfer', transfer_account_id = (select id from _acc where sfx = p.new_t), counterparty_id = null
    from _plan p where t.id = p.id and p.action = 'convert';
  get diagnostics n = row_count;
  if n <> 73 then raise exception '0095: преобразовано % строк', n; end if;

  values (team, null, 'Выписка Точки 1С 01.12.2023–16.10.2026 (сверка 0095)', null, 'tochka', 39, 'imported',
          'Операции, которых не было в сервисе; добавлены миграцией 0095')
  returning id into batch;

  with ins as (
                              status, origin, source, import_batch_id)
    select team, i.kind::tx_type, i.amount, 'RUB', (select id from _acc where sfx = i.frm),
           (select id from _acc where sfx = i.too), i.occurred_on, i.note, 'actual', 'bank_csv', 'statement_1c', batch
      from _ins i
    returning id)
  get diagnostics n = row_count;
  if n <> 39 then raise exception '0095: вставлено % строк вместо 39', n; end if;

  update accounts set opening_balance = 0 where id in (select id from _acc);

  -- 6. проверки «после»
  create temporary table _svc on commit drop as
  select a.sfx, to_char(e.dt, 'YYYY-MM') mon, sum(e.d)::bigint net from (
      select t.account_id acc, case t.type when 'income' then t.amount else -t.amount end d, t.occurred_on dt
        from transactions t where t.status = 'actual' and t.occurred_on <= '2026-10-16'
      union all
      select t.transfer_account_id, coalesce(t.transfer_amount, t.amount), t.occurred_on
        from transactions t where t.status = 'actual' and t.type = 'transfer' and t.occurred_on <= '2026-10-16') e
    join _acc a on a.id = e.acc group by 1, 2;

  select count(*) into n_bad from _bank_month b full join _svc s on s.sfx = b.sfx and s.mon = b.mon
   where coalesce(b.net, 0) <> coalesce(s.net, 0);
  if n_bad > 0 then raise exception '0095: обороты по % счёто-месяцам не совпали с выпиской', n_bad; end if;

  for r in select e.sfx, e.bal, a.opening_balance + coalesce((select sum(net) from _svc s where s.sfx = e.sfx), 0) svc
             from _bank_end e join _acc x on x.sfx = e.sfx join accounts a on a.id = x.id loop
    if r.svc <> r.bal then raise exception '0095: остаток …% на 16.10.2026 = %, в банке %', r.sfx, r.svc, r.bal; end if;
  end loop;

  select coalesce(sum(a.opening_balance), 0)
       + coalesce((select sum(case t.type when 'income' then t.amount else -t.amount end) from transactions t
                    where t.status = 'actual' and t.account_id not in (select id from _acc)), 0)
       + coalesce((select sum(coalesce(t.transfer_amount, t.amount)) from transactions t
                    where t.status = 'actual' and t.type = 'transfer' and t.transfer_account_id not in (select id from _acc)), 0)
    into other_after from accounts a where a.id not in (select id from _acc);
  if other_after <> other_before then
    raise exception '0095: изменился остаток других счетов (% -> %)', other_before, other_after;
  end if;

  raise notice '0095: удалено 50, изменено 234, добавлено 39; 16 счетов = выписка по месяцам и на 16.10.2026';

  if current_setting('recon0095.rehearsal', true) = 'on' then
    raise exception '0095 REHEARSAL OK: все проверки пройдены, изменения откатываются';
  end if;
end $$;
